N.median=a=>{const s=a.filter(x=>Number.isFinite(x)).slice().sort((a,b)=>a-b),n=s.length;return n?(n%2?s[(n-1)/2]:(s[n/2-1]+s[n/2])/2):null;};
vcsScore=()=>{const available=VCS2_CORE.filter(([k])=>Number.isFinite(VCS.res[k])),sum=available.reduce((a,[k])=>a+VCS.res[k],0),complete=available.length===VCS2_CORE.length;return {total:complete?sum:null,sum,nAvail:available.length,prorated:false,complete};};
