vcsIntro=()=>vcsFrame('검사 조건 확인',`<div class="vcs-big">시각인지 관찰 배터리</div><div class="ns-notice">핵심 5과제 · 내부 추적용(임상 규준 미검증). 표준 MMSE·MoCA·OCS를 대체하지 않습니다. 부분 시행은 총점을 환산하지 않고 시행한 영역만 저장합니다.</div><div class="ns-form-row"><div class="ns-field"><label for="nsVCoop">협조 · 각성</label><select id="nsVCoop"><option value="">선택</option><option>좋음</option><option>변동 있음</option><option>낮음</option></select></div><div class="ns-field"><label for="nsVFatigue">피로</label><select id="nsVFatigue"><option value="">선택</option><option>없음</option><option>약간</option><option>심함</option></select></div><div class="ns-field ns-wide"><label for="nsVLimits">시력·청력·실어증·운동 제한 (없으면 '제한 없음')</label><input id="nsVLimits" placeholder="예: 우측 손으로 터치 · 안경 착용"></div></div><label class="ns-choice"><input id="nsVProxy" type="checkbox"><span>치료사 대리 입력 · 반응시간은 운동/입력 보조 영향을 받음</span></label><div id="nsVError" class="ns-error" role="alert"></div>`,`<button class="btn vcs-btn" onclick="NS56.vcsBegin()">조건 확인 · 시작</button>`);
N.vcsBegin=()=>{if(!$('nsVCoop').value||!$('nsVFatigue').value||!$('nsVLimits').value.trim()){$('nsVError').textContent='협조·피로·검사 조건을 기록하세요.';return;}VCS.cond={coop:$('nsVCoop').value,fatigue:$('nsVFatigue').value,limits:$('nsVLimits').value.trim(),time:new Date().toISOString()};VCS.proxy=$('nsVProxy').checked;vcsMemEncode();};
