/* Keep the same menus and panel positions, and progressively disclose dense details. */
cogDomIcon=()=>'';
cogTodayHtml=async info=>{
 const rec=await cogRecommend(info),today=(await cogSessions(info.id)).filter(s=>cogDayOf(s.start)===cogToday());
 return `<section class="card"><div class="ns-section-header"><h3>보조 과제 제안</h3><span class="ns-small-label">최근 수행 기반 · 치료사 선택</span></div><p class="ns-muted">선택 프로토콜과 환자별 목표를 먼저 확인하세요. 과제 수행 점수는 인지 진단이나 실제 생활 기능의 총점이 아닙니다.</p><div class="cog-reclist">${rec.map(r=>`<div class="cog-rec"><span class="ns-step-num">${E(r.task.id)}</span><div style="flex:1"><b>${E(r.task.name)}</b><div class="ns-muted">${E(r.task.dom)} · ${E(r.task.purpose)}</div>${today.some(s=>s.task===r.task.id)?'<span class="ns-tag teal">오늘 시행 이력 있음</span>':''}</div><select id="cogLv_${r.task.id}" aria-label="과제 단계">${[1,2,3].map(n=>`<option value="${n}" ${n===r.level?'selected':''}>${COG_LV_NAME[n]}</option>`).join('')}</select><button class="btn ghost small" onclick="cogRun('${r.task.id}',+document.getElementById('cogLv_${r.task.id}').value)">시작</button></div>`).join('')}</div></section>`;
};
cogMenuHtml=async info=>{const levels=await cogLevels(info.id);return `<div class="cog-menu">${COG_DOMAINS.map(domain=>`<section class="card"><div class="ns-eyebrow">COGNITIVE TRAINING</div><h3 style="margin:0 0 12px">${E(domain)}</h3>${COG_TASKS.filter(t=>t.dom===domain).map(t=>{const level=levels[t.id]||cogDefaultLevel(info);return `<div class="cog-task"><div style="flex:1"><b>${E(t.name)}</b><div class="ns-muted">${E(t.id)} · ${E(t.purpose)}</div><details class="ns-proof" style="margin-top:8px"><summary>단계별 과제 구성</summary>${t.lv.map((v,i)=>`<p>${COG_LV_NAME[i+1]} · ${E(v)}</p>`).join('')}<p>단계 조절은 실제 수행과 도움 수준을 확인한 치료사가 결정합니다.</p></details></div><div class="rowbtns" style="flex-direction:column"><select id="cogM_${t.id}" aria-label="${E(t.name)} 단계">${[1,2,3].map(n=>`<option value="${n}" ${n===level?'selected':''}>${COG_LV_NAME[n]}</option>`).join('')}</select><button class="btn ghost small" onclick="cogRun('${t.id}',+document.getElementById('cogM_${t.id}').value)">시작</button></div></div>`;}).join('')}</section>`).join('')}</div>`;};
const originalCogHome=renderCogHome;
renderCogHome=async()=>{await originalCogHome();const el=$('cogHome');if(!el)return;const h=el.querySelector('h2 small');if(h)h.textContent='7영역 · 14과제 · 목표 기반 치료';if(currentPatientInfo&&dsPatients.some(p=>p.sysId===currentPatientInfo.id)&&window._cogView.tab==='today'){try{const tabs=el.querySelector('.deptsubtabs');tabs?.insertAdjacentHTML('afterend',await N.protocolPanel(currentPatientInfo));}catch(e){el.insertAdjacentHTML('beforeend',`<p class="ns-error">${E(e.message)}</p>`);}}N.decorate();N.storeRoute(false);};
