const originalPatient=renderTherapistPatient;
renderTherapistPatient=async el=>{await originalPatient(el);if(currentPatientInfo){const exam=el.querySelector('.thexam');if(exam){const mmse=[...exam.querySelectorAll('.thexam-item')].find(item=>item.querySelector('b')?.textContent.trim()==='MMSE');if(mmse){mmse.querySelector('b').textContent='표준 인지검사';const record=currentPatientInfo.scores?.standardCognitive;mmse.querySelector('.thexam-val').textContent=record?`${record.instrument} · ${record.total==null?'영역/부분 기록':record.total+'/30'}`:'실제 시행 결과 미등록';}const vcs=exam.querySelector('.thexam-vcs');if(vcs){vcs.querySelector('b').textContent='시각인지 관찰(VCS)';const v=currentPatientInfo.scores?.vcs;vcs.querySelector('.thexam-val').textContent=v?(v.total==null?`${v.nAvail||0}/5 영역 시행`:v.total+'/30 · 내부 점수'):'미시행';}}
 const cog=el.querySelector('.cog-box');if(cog&&!el.querySelector('.ns-cognitive-plan')){try{cog.insertAdjacentHTML('beforebegin',await N.protocolPanel(currentPatientInfo));}catch(e){cog.insertAdjacentHTML('beforebegin',`<p class="ns-error">${E(e.message)}</p>`);}}
 }N.decorate();};
