 const placeholder='<div class="ns-photo-empty"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.4" aria-hidden="true"><rect x="3" y="4" width="18" height="16" rx="3"/><circle cx="8" cy="9" r="1.5"/><path d="m4 17 5-5 4 4 3-3 4 4"/></svg><strong>치료 참고 사진</strong><span>병원 사진으로 교체</span></div>';
 h=h.replace('<span style="font-size:40px;">🏋️</span>',placeholder);h=h.replace(/<img src="([^"]+)">/g,(_,src)=>`<img src="${src}" alt="${E(s.label)} 참고 이미지" loading="lazy">`);return h;
