const originalDtOpen=dtOpen;
dtOpen=()=>{originalDtOpen();const card=document.querySelector('#dtOv .onb-card');if(card){const info=card.querySelector('.hint-small');if(info)info.textContent='병원 운영 초안 · 단계·빈도·진행 기준은 환자의 단일 수행, 인지/운동 제한과 안전을 함께 평가한 치료사가 결정합니다. 보편적인 임상 기준으로 검증된 수치가 아닙니다.';card.querySelectorAll('.dt-card img').forEach(img=>{const d=document.createElement('details');d.className='ns-proof';d.innerHTML='<summary>기존 참고 그림 보기</summary>';img.replaceWith(d);d.append(img);img.style.cssText='display:block;width:100%;max-width:320px;margin-top:10px';});const b=card.querySelector('button[onclick="dtDocOpen()"]');if(b)b.textContent='근거 검토';}N.decorate();};
